BEGIN;
SET LOCAL standard_conforming_strings = on;

INSERT INTO public.questions (
  id, year, question_type, subject, exam, question_number, topic, difficulty,
  statement, options, correct_option, explanation, source, is_annulled, is_published
) VALUES
('f8522f36-5395-5db1-a44a-73e0209479b1', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Linguagem de Programação', 'Fácil', 'No sistema gráfico padrão do componente, a origem fica normalmente:', '["Fora da janela.","No canto inferior direito.","No canto inferior esquerdo.","No centro sempre.","No canto superior esquerdo."]'::jsonb, 4, 'As coordenadas são relativas à área de desenho pertinente.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 13, seção 13.1, páginas 475–476 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d3e2a7e3-6391-54e3-a251-bde1b6381b8c', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Linguagem de Programação', 'Fácil', 'No sistema gráfico padrão, aumentar x move o ponto para:', '["A esquerda.","A direita.","Outra janela.","Cima.","Baixo."]'::jsonb, 1, 'O eixo horizontal cresce para a direita.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 13, seção 13.1, páginas 475–476 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('5fa12cee-3c0d-5da8-8843-7ae1aa2b396a', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Linguagem de Programação', 'Fácil', 'No sistema gráfico padrão, aumentar y move o ponto para:', '["O centro automaticamente.","Baixo.","A esquerda.","Cima.","A direita."]'::jsonb, 1, 'A orientação vertical difere do plano cartesiano escolar usual.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 13, seção 13.1, páginas 475–476 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('055b7cda-e979-5a65-ab8d-3c4db2fe5efb', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Linguagem de Programação', 'Médio', 'Graphics representa principalmente:', '["Um tipo primitivo.","Uma conexão de rede.","Um contexto para operações de desenho.","Um componente de botão.","Um arquivo de imagem obrigatório."]'::jsonb, 2, 'O contexto oferece operações de texto, formas e atributos gráficos.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 13, seção 13.2, páginas 477–482 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a93a890f-2bd3-558d-841e-443da0c3e40a', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Linguagem de Programação', 'Médio', 'Onde se costuma implementar desenho personalizado de JPanel?', '["close().","finalize().","main(Graphics g) obrigatoriamente.","compareTo().","paintComponent(Graphics g)."]'::jsonb, 4, 'O sistema chama paintComponent no ciclo de pintura do componente.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 13, seção 13.2, páginas 477–482 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ba6f982d-b963-5273-b7be-9ce19b86b6f6', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Linguagem de Programação', 'Médio', 'Por que chamar super.paintComponent(g) em uma sobrescrita usual?', '["Para executar main novamente.","Para criar um novo JFrame.","Para eliminar os eventos.","Para preservar a pintura básica, incluindo o fundo apropriado.","Para salvar em disco."]'::jsonb, 3, 'A omissão pode deixar artefatos e comprometer a atualização visual.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 13, seção 13.2, páginas 477–482 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ae07c372-fb03-5522-9a4d-d0465ebf2b49', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Linguagem de Programação', 'Médio', 'Para solicitar atualização visual de um componente, usa-se tipicamente:', '["repaint().","close().","runGc().","scan().","commit()."]'::jsonb, 0, 'A solicitação agenda uma nova pintura, não exige desenhar imediatamente no chamador.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 13, seção 13.2, páginas 477–482 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('eccc3c1f-00b1-5b60-89d7-b83051bb1f39', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Linguagem de Programação', 'Médio', '`new Color(255,0,0)` representa:', '["Preto.","Verde.","Branco.","Vermelho.","Azul."]'::jsonb, 3, 'No modelo RGB, o primeiro componente é a intensidade vermelha.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 13, seção 13.3, páginas 477–482 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('554d5078-d7e2-5fc5-a5f4-db878d973f78', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Linguagem de Programação', 'Médio', '`new Color(0,0,0)` representa:', '["Preto.","Branco.","Vermelho.","Amarelo.","Ciano."]'::jsonb, 0, 'Ausência de intensidade nos três canais produz preto.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 13, seção 13.3, páginas 477–482 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a1be8de0-21ed-553f-975b-d8bfd1ef5dea', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Linguagem de Programação', 'Médio', 'No construtor RGB com componentes int, o intervalo usual é:', '["1 a 100.","-128 a 127.","0 a 1 apenas.","Qualquer int sem validação.","0 a 255."]'::jsonb, 4, 'Valores fora do intervalo não são componentes RGB válidos nesse construtor.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 13, seção 13.3, páginas 477–482 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('51c6f412-6033-5191-8d87-8b05d1384e8d', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Linguagem de Programação', 'Médio', 'Uma Font combina informações como:', '["Somente posição x e y.","Somente cor RGB.","Família, estilo e tamanho.","Arquivo, senha e thread.","Apenas conteúdo do texto."]'::jsonb, 2, 'A fonte descreve como os caracteres devem ser apresentados.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 13, seção 13.4, páginas 483–486 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('2689a5c1-757f-55a2-895a-26d726b404e3', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Linguagem de Programação', 'Médio', 'FontMetrics ajuda a obter:', '["O endereço do arquivo.","O número de threads.","Medidas de texto na fonte utilizada.","O tipo de uma exceção.","Somente a cor de fundo."]'::jsonb, 2, 'Medidas auxiliam alinhamento e dimensionamento de texto.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 13, seção 13.4, páginas 483–486 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('fa926060-1a96-5a16-919d-86986a2acccc', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Linguagem de Programação', 'Médio', 'drawLine(x1,y1,x2,y2) recebe:', '["As coordenadas de dois extremos.","Duas larguras e duas alturas.","Quatro raios.","Quatro índices de fonte.","Um ponto e dois códigos de cor."]'::jsonb, 0, 'Os pontos definem o segmento desenhado.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 13, seção 13.5, páginas 487–489 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('bdfaceac-b5b0-5c91-9132-cb94044943d1', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Linguagem de Programação', 'Médio', 'Em drawRect(x,y,w,h), x e y indicam:', '["O canto inferior direito.","O número de pixels preenchidos.","As dimensões do retângulo.","O centro obrigatoriamente.","O canto superior esquerdo."]'::jsonb, 4, 'W e h descrevem largura e altura.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 13, seção 13.5, páginas 487–489 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f452a254-2904-5e49-94f7-47447aaf8b00', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Linguagem de Programação', 'Médio', 'Qual diferença entre drawRect e fillRect?', '["DrawRect não usa coordenadas.","Um desenha o contorno; o outro preenche a área.","DrawRect cria janela; fillRect fecha.","Ambos sempre preenchem.","FillRect só aceita círculos."]'::jsonb, 1, 'Os dois métodos usam a geometria do retângulo.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 13, seção 13.5, páginas 487–489 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('cef2f1dc-38ca-5ca1-a912-a0f50ce4915d', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Linguagem de Programação', 'Médio', 'drawOval(x,y,w,h) usa como referência:', '["Dois focos explicitamente.","O número de cores.","Um centro e um ângulo.","O retângulo delimitador do oval.","Somente um raio."]'::jsonb, 3, 'W e h iguais descrevem uma circunferência nessa área.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 13, seção 13.5, páginas 487–489 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a2e02210-6148-560a-9c33-cab2cc480e39', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Linguagem de Programação', 'Médio', 'Um arco é especificado, entre outros dados, por:', '["Apenas o número de vértices.","Somente dois nomes de fonte.","Ângulo inicial e extensão angular.","Um índice de array.","Um arquivo e uma senha."]'::jsonb, 2, 'Os parâmetros angulares determinam a parte da elipse representada.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 13, seção 13.6, páginas 490–491 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('601e63b6-7496-5f32-a96d-8d26522c6c3f', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Linguagem de Programação', 'Médio', 'Qual diferença geral entre polígono e polilinha?', '["Polígono só pode ter três pontos.","O polígono fecha a sequência; a polilinha não fecha necessariamente.","Ambos são apenas texto.","Polilinha sempre é circular.","Polígono não possui vértices."]'::jsonb, 1, 'Fechamento liga o último vértice ao primeiro.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 13, seção 13.7, páginas 492–493 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('5d71d7a6-9f26-5c91-b7de-54a14817cb0f', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Linguagem de Programação', 'Médio', 'Graphics2D amplia o desenho com recursos como:', '["Apenas entrada de teclado.","Consultas SQL.","Bloqueios de thread.","Traços, preenchimentos e transformações.","Somente impressão de strings."]'::jsonb, 3, 'A API oferece controle gráfico mais rico.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 13, seção 13.8, páginas 494–498 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('18465334-85c1-513b-a5b2-2de728531900', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Linguagem de Programação', 'Médio', 'BasicStroke é usado principalmente para configurar:', '["Características do traço.","O banco de dados.","A serialização de objetos.","O conteúdo textual.","O modelo de seleção."]'::jsonb, 0, 'Espessura e estilo do traçado são propriedades de stroke.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 13, seção 13.8, páginas 494–498 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false)
ON CONFLICT (id) DO NOTHING;

COMMIT;
